function return_pos_proforma_to_draft(int $proformaId,array $actor): array {$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT * FROM proforma_invoices WHERE id=? FOR UPDATE');$q->execute([$proformaId]);$proforma=$q->fetch();if(!$proforma||$proforma['status']==='cancelled')throw new RuntimeException('This POS proforma cannot be returned to editing');require_branch_access($actor,(int)$proforma['branch_id']);if((int)$proforma['branch_id']!==active_branch_id($actor))throw new RuntimeException('Switch to the proforma branch before returning it');$q=$pdo->prepare('SELECT id,sale_reference,total FROM sales WHERE proforma_id=? FOR UPDATE');$q->execute([$proformaId]);$sales=$q->fetchAll();$saleIds=array_map(static fn($r)=>(int)$r['id'],$sales);$restored=0;$invoiceAudit=[];foreach($sales as $sale){$saleId=(int)$sale['id'];$q=$pdo->prepare('SELECT product_id,quantity_units FROM sale_items WHERE sale_id=? ORDER BY id FOR UPDATE');$q->execute([$saleId]);foreach($q->fetchAll() as $item){$pid=(int)$item['product_id'];$units=(int)$item['quantity_units'];$lock=$pdo->prepare('SELECT stock_units FROM branch_inventory WHERE branch_id=? AND product_id=? FOR UPDATE');$lock->execute([(int)$proforma['branch_id'],$pid]);$before=$lock->fetchColumn();if($before===false)throw new RuntimeException('A sold product no longer has an inventory record');$after=(int)$before+$units;$pdo->prepare('UPDATE branch_inventory SET stock_units=? WHERE branch_id=? AND product_id=?')->execute([$after,(int)$proforma['branch_id'],$pid]);$q=$pdo->prepare('SELECT units_per_box FROM products WHERE id=?');$q->execute([$pid]);$pack=(int)$q->fetchColumn();$pdo->prepare("INSERT INTO stock_movements(product_id,movement_type,reference_type,reference_id,quantity_before,quantity_in,quantity_out,quantity_after,units_per_box_snapshot,performed_by,branch_id,notes) VALUES(?,'release','pos_return',?,?,?,0,?,?,?,?, 'POS sale reversed and returned for editing')")->execute([$pid,$saleId,(int)$before,$units,$after,$pack,$actor['id'],(int)$proforma['branch_id']]);$restored+=$units;}$q=$pdo->prepare('SELECT id,invoice_reference,total FROM invoices WHERE sale_id=? FOR UPDATE');$q->execute([$saleId]);$invoiceAudit=array_merge($invoiceAudit,$q->fetchAll());$pdo->prepare('DELETE FROM invoices WHERE sale_id=?')->execute([$saleId]);$pdo->prepare('DELETE FROM sale_items WHERE sale_id=?')->execute([$saleId]);$pdo->prepare('DELETE FROM sales WHERE id=?')->execute([$saleId]);}$q=$pdo->prepare('SELECT id,payment_reference,amount,verification_status FROM payments WHERE proforma_id=? FOR UPDATE');$q->execute([$proformaId]);$paymentAudit=$q->fetchAll();$pdo->prepare("UPDATE payments SET verification_status='rejected',rejection_reason='Voided and returned to POS for editing',reviewed_by=?,reviewed_at=NOW() WHERE proforma_id=? AND verification_status<>'rejected'")->execute([$actor['id'],$proformaId]);$pdo->prepare("UPDATE proforma_invoices SET status='pending_payment',expires_at=DATE_ADD(NOW(),INTERVAL 1 DAY) WHERE id=?")->execute([$proformaId]);audit('finance.return_to_pos','proforma',$proformaId,['sales'=>$sales,'payments'=>$paymentAudit,'restored_units'=>$restored]);$pdo->commit();return ['proforma_id'=>$proformaId,'proforma_reference'=>$proforma['proforma_reference'],'restored_units'=>$restored];}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
if($path==='/share'&&$method==='GET'){$settings=array_column(db()->query('SELECT setting_key,setting_value FROM pharmacy_settings')->fetchAll(),'setting_value','setting_key');$name=trim((string)($settings['pharmacy_name']??''))?:'Pharmacy';$heading=trim((string)($settings['hero_title']??''))?:'Professional Pharmacy Care';$title=$name.' | '.$heading;$description=trim(preg_replace('/\\s+/u',' ',(string)(($settings['hero_text']??'').' '.($settings['about_text']??''))));if($description==='')$description='Professional pharmacy care, quality medicines and health products from '.$name.'.';$description=mb_substr($description,0,300);$logo=trim((string)($settings['logo_url']??''));if($logo!==''&&!preg_match('#^https?://#i',$logo))$logo=rtrim(envv('APP_URL',''),'/').'/'.ltrim($logo,'/');$origins=array_values(array_filter(array_map('trim',explode(',',envv('FRONTEND_ORIGIN','http://localhost:5173')))));$frontend=$origins[0]??'/';$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');header_remove('Content-Type');header('Content-Type: text/html; charset=utf-8');$image=$logo!==''?'<meta property="og:image" content="'.$esc($logo).'"><meta property="og:image:alt" content="'.$esc($name).' logo"><meta name="twitter:image" content="'.$esc($logo).'">':'';echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.$esc($title).'</title><meta name="description" content="'.$esc($description).'"><meta property="og:type" content="website"><meta property="og:title" content="'.$esc($title).'"><meta property="og:site_name" content="'.$esc($name).'"><meta property="og:description" content="'.$esc($description).'">'.$image.'<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="'.$esc($title).'"><meta name="twitter:description" content="'.$esc($description).'"><link rel="canonical" href="'.$esc($frontend).'/"></head><body><p>Opening '.$esc($title).'. <a