if($path==='/settings/branches'&&$method==='POST'){ $actor=require_auth();if($actor['role']!=='Administrator')respond(['error'=>'Administrator access required to create branches'],403);csrf_check();$in=json_input();$name=body_string($in,'name',160,true);$email=body_string($in,'contact_email',190);$map=body_string($in,'map_link',1000);if(($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))||($map!==''&&!filter_var($map,FILTER_VALIDATE_URL)))respond(['error'=>'Enter a valid branch contact email and Google Maps URL'],422);try{$pdo=db();$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO branches(name,location,address,phone,contact_email,map_link,payment_instructions) VALUES(?,?,?,?,?,?,?)');$q->execute([$name,body_string($in,'location',240),body_string($in,'address',2000),body_string($in,'phone',50),$email?:null,$map?:null,body_string($in,'payment_instructions',4000)]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO branch_inventory(branch_id,product_id,stock_units,box_price,cost_price) SELECT ?,id,0,box_price,cost_price FROM products')->execute([$id]);$pdo->commit();audit('branch.create','branch',$id,['name'=>$name,'actor_id'=>$actor['id']]);respond(['id'=>$id],201);}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log('Branch creation failed: '.$e->getMessage());$message=$e instanceof PDOException&&str_contains($e->getMessage(),'Duplicate entry')?'A branch with this name already exists':'Unable to create branch. Check the branch details and database error log.';respond(['error'=>$message],422);}}
if(preg_match('#^/settings/branches/(\d+)$#',$path,$m)&&$method==='PUT'){ $actor=require_auth();$id=(int)$m[1];if($actor['role']!=='Administrator')respond(['error'=>'Administrator access required'],403);csrf_check();$in=json_input();$name=body_string($in,'name',160,true);$email=body_string($in,'contact_email',190);$map=body_string($in,'map_link',1000);if(($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))||($map!==''&&!filter_var($map,FILTER_VALIDATE_URL)))respond(['error'=>'Enter a valid branch contact email and Google Maps URL'],422);$active=$actor['role']==='Administrator'?(array_key_exists('active',$in)?(!empty($in['active'])?1:0):1):1;try{$q=db()->prepare('UPDATE branches SET name=?,location=?,address=?,phone=?,contact_email=?,map_link=?,payment_instructions=?,active=? WHERE id=?');$q->execute([$name,body_string($in,'location',240),body_string($in,'address',2000),body_string($in,'phone',50),$email?:null,$map?:null,body_string($in,'payment_instructions',4000),$active,$id]);}catch(PDOException $e){if((string)$e->getCode()==='23000')respond(['error'=>'A branch with this name already exists'],422);throw $e;}if(!$q->rowCount()&&!db()->query('SELECT 1 FROM branches WHERE id='.(int)$id)->fetchColumn())respond(['error'=>'Branch not found'],404);audit('branch.update','branch',$id,['actor_id'=>$actor['id']]);respond(['ok'=>true]);}
