if(preg_match('#^/settings/branches/(\d+)$#',$path,$m)&&$method==='DELETE'){$actor=require_auth();if($actor['role']!=='Administrator'&&!in_array('orders.process',$actor['permissions']??[],true))respond(['error'=>'Administrator or branch management access required'],403);csrf_check();$id=(int)$m[1];if($actor['role']!=='Administrator')require_branch_access($actor,$id);$pdo=db();$q=$pdo->prepare('SELECT name,active FROM branches WHERE id=?');$q->execute([$id]);$branch=$q->fetch();if(!$branch)respond(['error'=>'Branch not found'],404);if((int)$branch['active']===1){$pdo->prepare('UPDATE branches SET active=0 WHERE id=?')->execute([$id]);audit('branch.archive','branch',$id,['branch_name'=>$branch['name'],'actor_id'=>$actor['id']]);respond(['ok'=>true,'archived'=>true]);}if($actor['role']!=='Administrator')respond(['error'=>'Only an Administrator can permanently delete an inactive branch'],403);try{$pdo->beginTransaction();$staffQ=$pdo->prepare('SELECT COUNT(*) FROM user_branches WHERE branch_id=?');$staffQ->execute([$id]);if((int)$staffQ->fetchColumn()>0)throw new RuntimeException('Reassign staff from this branch before deleting it.');$stockQ=$pdo->prepare('SELECT COALESCE(SUM(stock_units),0) FROM branch_inventory WHERE branch_id=?');$stockQ->execute([$id]);if((int)$stockQ->fetchColumn()>0)throw new RuntimeException('This branch still has stock. Transfer or adjust its stock before deletion.');audit('branch.delete','branch',$id,['branch_name'=>$branch['name'],'actor_id'=>$actor['id']]);$pdo->prepare('DELETE FROM branch_inventory WHERE branch_id=?')->execute([$id]);$pdo->prepare('DELETE FROM branches WHERE id=? AND active=0')->execute([$id]);$pdo->commit();respond(['ok'=>true,'deleted'=>true]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();if($e instanceof RuntimeException)respond(['error'=>$e->getMessage()],409);if($e instanceof PDOException&&(string)$e->getCode()==='23000')respond(['error'=>'This inactive branch has historical records and cannot be perman