if($path==='/reports/overall'&&$method==='GET'){
 $actor=require_auth();if($actor['role']!=='Administrator')respond(['error'=>'Administrator access required'],403);
 $from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??date('Y-m-d'));
 if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)||$from>$to)respond(['error'=>'Choose a valid report date range'],422);
 $pdo=db();
 $q=$pdo->prepare("SELECT b.id branch_id,b.name branch_name,COALESCE(inv.units,0) inventory_units,COALESCE(inv.stock_value,0) stock_value,COALESCE(sales.amount,0) sales,COALESCE(exp.amount,0) expenses,COALESCE(pending.amount,0) unpaid_invoices FROM branches b LEFT JOIN (SELECT bi.branch_id,SUM(bi.stock_units) units,SUM(FLOOR(bi.stock_units/p.units_per_box)*COALESCE(bi.cost_price,p.cost_price)) stock_value FROM branch_inventory bi JOIN products p ON p.id=bi.product_id WHERE p.is_active=1 GROUP BY bi.branch_id) inv ON inv.branch_id=b.id LEFT JOIN (SELECT branch_id,SUM(amount) amount FROM (SELECT pi.branch_id,i.total amount,DATE(i.created_at) report_date FROM invoices i JOIN sales s ON s.id=i.sale_id JOIN proforma_invoices pi ON pi.id=s.proforma_id WHERE i.invoice_status='issued' UNION ALL SELECT o.branch_id,oi.total amount,DATE(oi.created_at) report_date FROM order_invoices oi JOIN orders o ON o.id=oi.order_id) all_sales WHERE report_date BETWEEN ? AND ? GROUP BY branch_id) sales ON sales.branch_id=b.id LEFT JOIN (SELECT branch_id,SUM(amount) amount FROM expenses WHERE expense_date BETWEEN ? AND ? GROUP BY branch_id) exp ON exp.branch_id=b.id LEFT JOIN (SELECT branch_id,SUM(subtotal) amount FROM orders WHERE payment_status='unpaid' AND status IN ('confirmed','partially_confirmed') AND DATE(created_at) BETWEEN ? AND ? GROUP BY branch_id) pending ON pending.branch_id=b.id WHERE b.active=1 ORDER BY b.name");
 $q->execute([$from,$to,$from,$to,$from,$to]);$rows=$q->fetchAll();foreach($rows as &$r){foreach(['inventory_units','stock_value','sales','expenses','unpaid_invoices'] as $k)$r[$k]=(float)$r[$k];$r['income']=$r['sales']-$r['expenses'];}unset($r);
 $categories=[];$add=static function(array $row)use(&$categories){$key=(int)$row['branch_id'].'|'.(string)$row['category'];if(!isset($categories[$key]))$categories[$key]=['branch_id'=>(int)$row['branch_id'],'category'=>(string)$row['category'],'sales'=>0.0,'expenses'=>0.0,'stock_value'=>0.0,'inventory_units'=>0.0];foreach(['sales','expenses','stock_value','inventory_units'] as $k)$categories[$key][$k]+=(float)($row[$k]??0);};
 $q=$pdo->query("SELECT bi.branch_id,COALESCE(pc.name,'Uncategorized') category,SUM(bi.stock_units) inventory_units,SUM(FLOOR(bi.stock_units/p.units_per_box)*COALESCE(bi.cost_price,p.cost_price)) stock_value FROM branch_inventory bi JOIN products p ON p.id=bi.product_id LEFT JOIN product_categories pc ON pc.id=p.category_id WHERE p.is_active=1 GROUP BY bi.branch_id,COALESCE(pc.name,'Uncategorized')");foreach($q->fetchAll() as $r)$add($r);
 $q=$pdo->prepare("SELECT pi.branch_id,COALESCE(pc.name,'Uncategorized') category,SUM(si.line_total) sales FROM invoices i JOIN sales s ON s.id=i.sale_id JOIN proforma_invoices pi ON pi.id=s.proforma_id JOIN sale_items si ON si.sale_id=s.id JOIN products p ON p.id=si.product_id LEFT JOIN product_categories pc ON pc.id=p.category_id WHERE i.invoice_status='issued' AND DATE(i.created_at) BETWEEN ? AND ? GROUP BY pi.branch_id,COALESCE(pc.name,'Uncategorized')");$q->execute([$from,$to]);foreach($q->fetchAll() as $r)$add($r);
 $q=$pdo->prepare("SELECT o.branch_id,COALESCE(pc.name,'Uncategorized') category,SUM(oi.line_total) sales FROM order_invoices iv JOIN orders o ON o.id=iv.order_id JOIN order_items oi ON oi.order_id=o.id JOIN products p ON p.id=oi.product_id LEFT JOIN product_categories pc ON pc.id=p.category_id WHERE DATE(iv.created_at) BETWEEN ? AND ? AND oi.line_total IS NOT NULL GROUP BY o.branch_id,COALESCE(pc.name,'Uncategorized')");$q->execute([$from,$to]);foreach($q->fetchAll() as $r)$add($r);
 $q=$pdo->prepare("SELECT branch_id,category,SUM(amount) expenses FROM expenses WHERE expense_date BETWEEN ? AND ? GROUP BY branch_id,category");$q->execute([$from,$to]);foreach($q->fetchAll() as $r)$add($r);
 $branchNames=[];foreach($rows as $r)$branchNames[(int)$r['branch_id']]=$r['branch_name'];$categoryRows=array_values($categories);foreach($categoryRows as &$r)$r['branch_name']=$branchNames[$r['branch_id']]??'';unset($r);usort($categoryRows,static fn($a,$b)=>[$a['category'],$a['branch_name']]<=>[$b['category'],$b['branch_name']]);
 audit('reports.overall.view','report',null,['from'=>$from,'to'=>$to,'branch_count'=>count($rows)]);
 respond(['from'=>$from,'to'=>$to,'branches'=>$rows,'categories'=>$categoryRows,'totals'=>['inventory_units'=>array_sum(array_column($rows,'inventory_units')),'stock_value'=>array_sum(array_column($rows,'stock_value')),'sales'=>array_sum(array_column($rows,'sales')),'expenses'=>array_sum(array_column($rows,'expenses')),'income'=>array_sum(array_column($rows,'income')),'unpaid_invoices'=>array_sum(array_column($rows,'unpaid_invoices'))]]);
