,line_total=? WHERE id=?')->execute([$boxes,$stock['box_price'],$line,$it['id']]);}else{$pdo->prepare('UPDATE order_items SET confirmed_boxes=0,box_price_snapshot=NULL,line_total=NULL WHERE id=?')->execute([$it['id']]);}}if(!$confirmed)throw new RuntimeException('No available quantities to confirm');$status=$confirmed>=array_sum(array_column($items,'requested_boxes'))?'confirmed':'partially_confirmed';$pdo->prepare('UPDATE orders SET status=?,subtotal=? WHERE id=?')->execute([$status,$total,$oid]);$pdo->commit();audit('order.confirm','order',$oid,['status'=>$status,'stock_deducted'=>false]);$q=db()->prepare('SELECT c.email,c.phone,c.full_name,o.order_reference,o.branch_id,b.name branch_name,b.payment_instructions,b.phone branch_phone,b.contact_email branch_email FROM orders o JOIN branches b ON b.id=o.branch_id JOIN customers c ON c.id=o.customer_id WHERE o.id=?');$q->execute([$oid]);$customer=$q->fetch();if($customer){$financeAddresses=branch_finance_email_addresses((int)$customer['branch_id']);$receiptEmail=$financeAddresses?implode(', ',$financeAddresses):($customer['branch_email']?:'contact the branch');$paymentDetails='Payment details for '.$customer['branch_name'].': '.($customer['payment_instructions']?:'Contact the branch to arrange payment.').' Branch phone: '.($customer['branch_phone']?:'not provided').'. Receipt email: '.$receiptEmail.'.';$emailBody='Hello '.$customer['full_name'].','.PHP_EOL.PHP_EOL.'Order '.$customer['order_reference'].' at '.$customer['branch_name'].' is '.$status.' and is now waiting for payment. Confirmed total: TZS '.number_format($total,0).'.'.PHP_EOL.PHP_EOL.$paymentDetails;if($customer['email'])send_branded_email($customer['email'],'Your order is confirmed - payment is next',$emailBody,order_pdf_attachment($oid),order_email_preview_html($oid,true));$smsSent=!empty($customer['phone'])?send_sms($customer['phone'],$customer['branch_name'].' order '.$customer['order_reference'].' confirmed, awaiting payment. Total TZS '.number_format