 $pdo=db();
 $q=$pdo->prepare("SELECT DATE(COALESCE(p.reviewed_at,p.submitted_at,pi.created_at)) report_date,'POS sale' record_type,COALESCE(p.payment_reference,pi.proforma_reference) reference,CASE WHEN p.verification_status='approved' THEN 'paid' WHEN p.verification_status='pending' THEN 'pending' WHEN p.verification_status='rejected' OR pi.status='rejected' THEN 'rejected' ELSE 'unpaid' END status,COALESCE(p.verification_status,'unpaid') payment_status,pi.status workflow_status,c.full_name customer_name,c.email customer_email,c.phone customer_phone,p.payment_method,p.transaction_reference,pi.grand_total amount,iv.invoice_reference FROM proforma_invoices pi LEFT JOIN payments p ON p.proforma_id=pi.id LEFT JOIN customers c ON c.id=pi.customer_id LEFT JOIN sales s ON s.proforma_id=pi.id LEFT JOIN invoices iv ON iv.sale_id=s.id WHERE pi.branch_id=? AND DATE(COALESCE(p.reviewed_at,p.submitted_at,pi.created_at)) BETWEEN ? AND ? ORDER BY report_date,pi.id");
